ALTER TABLE public.clients ADD COLUMN document text NOT NULL DEFAULT '', ADD COLUMN person_type text NOT NULL DEFAULT 'Pessoa física', ADD COLUMN postal_code text NOT NULL DEFAULT '', ADD COLUMN street text NOT NULL DEFAULT '', ADD COLUMN address_number text NOT NULL DEFAULT '', ADD COLUMN complement text NOT NULL DEFAULT '', ADD COLUMN neighborhood text NOT NULL DEFAULT '', ADD COLUMN city text NOT NULL DEFAULT '', ADD COLUMN state text NOT NULL DEFAULT '', ADD COLUMN notes text NOT NULL DEFAULT '';
CREATE TABLE public.bank_accounts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), owner_id uuid NOT NULL DEFAULT auth.uid(), name text NOT NULL, bank text NOT NULL DEFAULT '', agency text NOT NULL DEFAULT '', account_number text NOT NULL DEFAULT '', pix_key text NOT NULL DEFAULT '', opening_balance numeric(12,2) NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE, DELETE ON public.bank_accounts TO authenticated; GRANT ALL ON public.bank_accounts TO service_role;
ALTER TABLE public.bank_accounts ENABLE ROW LEVEL SECURITY;
CREATE POLICY banks_owner ON public.bank_accounts FOR ALL TO authenticated USING(owner_id=auth.uid()) WITH CHECK(owner_id=auth.uid());
CREATE TABLE public.financial_entries (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), owner_id uuid NOT NULL DEFAULT auth.uid(), bank_account_id uuid REFERENCES public.bank_accounts(id), order_id uuid REFERENCES public.service_orders(id), description text NOT NULL, kind text NOT NULL CHECK(kind IN ('Receita','Despesa')), amount numeric(12,2) NOT NULL CHECK(amount>0), due_date date NOT NULL, paid_date date, category text NOT NULL DEFAULT '', payment_method text NOT NULL DEFAULT 'Pix', created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE, DELETE ON public.financial_entries TO authenticated; GRANT ALL ON public.financial_entries TO service_role;
ALTER TABLE public.financial_entries ENABLE ROW LEVEL SECURITY;
CREATE POLICY finance_owner ON public.financial_entries FOR ALL TO authenticated USING(owner_id=auth.uid()) WITH CHECK(owner_id=auth.uid() AND (bank_account_id IS NULL OR EXISTS(SELECT 1 FROM public.bank_accounts b WHERE b.id=bank_account_id AND b.owner_id=auth.uid())) AND (order_id IS NULL OR EXISTS(SELECT 1 FROM public.service_orders o WHERE o.id=order_id AND o.owner_id=auth.uid())));
CREATE UNIQUE INDEX one_order_receivable ON public.financial_entries(order_id) WHERE order_id IS NOT NULL AND kind='Receita';
CREATE INDEX entries_owner_due ON public.financial_entries(owner_id,due_date);